class Solution { fun longestPath(parent:IntArray,s:String):Int{val n=parent.size;val children=Array(n){mutableListOf<Int>()};for(i in 1 until n)children[parent[i]].add(i);val order=IntArray(n);var size=0;val stack=java.util.ArrayDeque<Int>();stack.add(0);while(stack.isNotEmpty()){val node=stack.removeLast();order[size++]=node;for(child in children[node])stack.add(child)};val down=IntArray(n);var answer=1;for(index in n-1 downTo 0){val node=order[index];var first=0;var second=0;for(child in children[node])if(s[child]!=s[node]){val value=down[child];if(value>first){second=first;first=value}else if(value>second)second=value};down[node]=first+1;answer=maxOf(answer,first+second+1)};return answer} }
